import { test, expect } from '@playwright/test';

test.describe('Async Form Submission - Submit Button Disabling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should disable submit button while form is being submitted asynchronously', async ({ page }) => {
    // Intercept the API call
    await page.route('**/api/form-submit', (route) => {
      route.abort('API call failed');
    });

    // Get the submit button by role
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Get the form input by label
    const nameInput = page.getByLabel(/name/i);
    await expect(nameInput).toBeVisible();

    // Get the email input by label
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();

    // Fill in the form fields
    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');

    // Click the submit button
    await submitButton.click();

    // Verify the button is disabled
    await expect(submitButton).toBeDisabled();

    // Verify the loading state is visible
    const loadingIndicator = page.getByText(/submitting.../i);
    await expect(loadingIndicator).toBeVisible();

    // Verify the form is still visible
    const formContainer = page.locator('[data-testid="form-container"]');
    await expect(formContainer).toBeVisible();

    // Verify the error message is displayed
    const errorMessage = page.getByText(/submission failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify the form is still editable
    await expect(nameInput).toBeEditable();
    await expect(emailInput).toBeEditable();
  });

  test('should re-enable submit button after successful async form submission', async ({ page }) => {
    // Mock successful API response
    await page.route('**/api/form-submit', (route) => {
      route.continue();
    });

    // Get the submit button by role
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Get the form input by label
    const nameInput = page.getByLabel(/name/i);
    await expect(nameInput).toBeVisible();

    // Get the email input by label
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();

    // Fill in the form fields
    await nameInput.fill('Jane Smith');
    await emailInput.fill('jane@example.com');

    // Click the submit button
    await submitButton.click();

    // Verify the button is now enabled
    await expect(submitButton).not.toBeDisabled();

    // Verify the loading state is gone
    const loadingIndicator = page.getByText(/submitting.../i);
    await expect(loadingIndicator).not.toBeVisible();

    // Verify the success message is displayed
    const successMessage = page.getByText(/form submitted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the form is still editable
    await expect(nameInput).toBeEditable();
    await expect(emailInput).toBeEditable();
  });
});
